import React, { useState, useCallback, useEffect, useRef } from "react";
import getDiscourseNodes, { DiscourseNode } from "~/utils/getDiscourseNodes";
import { getSubTree } from "roamjs-components/util";
import { InputGroup, ControlGroup, Tooltip, Icon } from "@blueprintjs/core";
import DiscourseNodeSpecification from "./DiscourseNodeSpecification";
import DiscourseNodeAttributes from "./DiscourseNodeAttributes";
import DiscourseNodeCanvasSettings, {
  formatHexColor,
} from "./DiscourseNodeCanvasSettings";
import setInputSetting from "roamjs-components/util/setInputSetting";
import {
  getDiscourseNodeSetting,
  isSyncEnabled,
  setDiscourseNodeSetting,
} from "~/components/settings/utils/accessors";
import {
  CANVAS_KEYS,
  DISCOURSE_NODE_KEYS,
  SPECIFICATION_KEYS,
  TEMPLATE_SETTING_KEYS,
} from "~/components/settings/utils/settingKeys";
import DiscourseNodeSuggestiveRules from "./DiscourseNodeSuggestiveRules";
import { getNodeTagStyles } from "~/utils/getDiscourseNodeColors";
import {
  DiscourseNodeTextPanel,
  DiscourseNodeFlagPanel,
  DiscourseNodeSelectPanel,
} from "./components/BlockPropSettingPanels";
import { ROAM_DOCS, withDocsLink } from "./utils/docs";
import { SettingsGroup } from "./components/SettingsHeadings";
import SettingItemRow from "./components/SettingItemRow";
import SettingDrillDownSummary from "./components/SettingDrillDownSummary";
import { useSettingsNav } from "./navigation/SettingsNavContext";
import { nodeConfigSegmentIds } from "./utils/settingsNavigation";
import {
  CollapsedSections,
  NODE_CONFIG_SECTIONS,
} from "./utils/nodeConfigSections";

export const getCleanTagText = (tag: string): string => {
  return tag.replace(/^#+/, "").trim().toUpperCase();
};

const COLOR_WRITE_DEBOUNCE_MS = 150;

type DiscourseNodeColorSettingProps = {
  canvasUid: string;
  nodeType: string;
  initialColor?: string;
  tagValue: string;
};

const DiscourseNodeColorSetting = ({
  canvasUid,
  nodeType,
  initialColor,
  tagValue,
}: DiscourseNodeColorSettingProps): React.ReactElement => {
  const [color, setColor] = useState<string>(() =>
    formatHexColor(initialColor ?? ""),
  );
  const colorWriteTimeoutRef = useRef<number | null>(null);

  const persistColorValue = useCallback(
    (colorValue: string): void => {
      void setInputSetting({
        blockUid: canvasUid,
        key: "color",
        value: colorValue,
      });
      setDiscourseNodeSetting(
        nodeType,
        [DISCOURSE_NODE_KEYS.canvasSettings, CANVAS_KEYS.color],
        colorValue,
      );
    },
    [canvasUid, nodeType],
  );

  useEffect(() => {
    return () => {
      if (!colorWriteTimeoutRef.current) return;

      window.clearTimeout(colorWriteTimeoutRef.current);
    };
  }, []);

  const persistColorAfterPause = (colorValue: string): void => {
    if (colorWriteTimeoutRef.current) {
      window.clearTimeout(colorWriteTimeoutRef.current);
      colorWriteTimeoutRef.current = null;
    }
    colorWriteTimeoutRef.current = window.setTimeout(() => {
      persistColorValue(colorValue);
      colorWriteTimeoutRef.current = null;
    }, COLOR_WRITE_DEBOUNCE_MS);
  };

  return (
    <>
      {tagValue && (
        <div className="flex items-center gap-1.5 pl-1">
          <span className="text-xs italic text-gray-400">Preview:</span>
          <span style={color ? getNodeTagStyles(color) : undefined}>
            #{tagValue.replace(/^#/, "")}
          </span>
        </div>
      )}
      <SettingItemRow
        label="Color"
        description="Changes the color of tags and canvas nodes"
        scope="global"
        settingKeys={[DISCOURSE_NODE_KEYS.canvasSettings, CANVAS_KEYS.color]}
        control={(controlId) => (
          <ControlGroup>
            <InputGroup
              id={controlId}
              style={{ width: 120 }}
              type={"color"}
              value={color}
              onChange={(e) => {
                const nextColor = e.target.value;
                const colorValue = nextColor.replace("#", ""); // remove hash to not create roam link
                setColor(nextColor);
                persistColorAfterPause(colorValue);
              }}
            />
            <Tooltip content={color ? "Unset" : "Color not set"}>
              <Icon
                className={"ml-2 align-middle opacity-80"}
                icon={color ? "delete" : "info-sign"}
                onClick={() => {
                  if (colorWriteTimeoutRef.current) {
                    window.clearTimeout(colorWriteTimeoutRef.current);
                    colorWriteTimeoutRef.current = null;
                  }
                  setColor("");
                  persistColorValue("");
                }}
              />
            </Tooltip>
          </ControlGroup>
        )}
      />
    </>
  );
};

const generateTagPlaceholder = (node: DiscourseNode): string => {
  // Extract first reference from format like [[CLM]], [[QUE]], [[EVD]]
  const referenceMatch = node.format.match(/\[\[([A-Z]+)\]\]/);

  if (referenceMatch) {
    const reference = referenceMatch[1].toLowerCase();
    return `#${reference.slice(0, 3)}-candidate`; // [[EVD]] - {content} = #evd-candidate
  }

  const nodeTextPrefix = node.text.toLowerCase().slice(0, 3);
  return `#${nodeTextPrefix}-candidate`; // Evidence = #evi-candidate
};

const NodeConfig = ({
  node,
  collapsedSections,
  onToggleSection,
}: {
  node: DiscourseNode;
  collapsedSections: CollapsedSections;
  onToggleSection: (section: string) => void;
}) => {
  const sectionProps = (
    title: string,
  ): Omit<React.ComponentProps<typeof SettingsGroup>, "children"> => ({
    title,
    collapsible: {
      isOpen: !collapsedSections.has(title),
      onToggle: () => onToggleSection(title),
    },
  });
  const getUid = (key: string) =>
    getSubTree({
      parentUid: node.type,
      key: key,
    }).uid;
  const formatUid = getUid("Format");
  const descriptionUid = getUid("Description");
  const shortcutUid = getUid("Shortcut");
  const tagUid = getUid("Tag");
  const overlayUid = getUid("Overlay");
  const canvasUid = getUid("Canvas");
  const graphOverviewUid = getUid("Graph Overview");
  const specificationUid = getUid("Specification");
  const suggestiveRulesUid = getUid("Suggestive Rules");
  const attributeNode = getSubTree({
    parentUid: node.type,
    key: "Attributes",
  });

  const nav = useSettingsNav();
  const [tagError, setTagError] = useState("");
  const [formatError, setFormatError] = useState("");
  const [shortcutError, setShortcutError] = useState("");

  const [tagValue, setTagValue] = useState(node.tag || "");
  const [formatValue, setFormatValue] = useState(node.format || "");
  const [shortcutValue, setShortcutValue] = useState(node.shortcut || "");
  const validate = useCallback(
    ({
      tag,
      format,
      isSpecificationEnabled,
    }: {
      tag: string;
      format: string;
      isSpecificationEnabled?: boolean;
    }) => {
      if (isSpecificationEnabled === undefined)
        isSpecificationEnabled =
          getDiscourseNodeSetting<boolean>(node.type, [
            DISCOURSE_NODE_KEYS.specification,
            SPECIFICATION_KEYS.enabled,
          ]) ?? false;
      if (format.trim().length === 0 && !isSpecificationEnabled) {
        setTagError("");
        setFormatError("Error: you must set either a format or specification");
        return;
      }
      const cleanTag = getCleanTagText(tag);

      if (!cleanTag) {
        setTagError("");
        setFormatError("");
        return;
      }

      const roamTagRegex = /#?\[\[(.*?)\]\]|#(\S+)/g;
      const matches = format.matchAll(roamTagRegex);
      const formatTags: string[] = [];
      for (const match of matches) {
        const tagName = match[1] || match[2];
        if (tagName) {
          formatTags.push(tagName.toUpperCase());
        }
      }

      const hasConflict = formatTags.includes(cleanTag);

      if (hasConflict) {
        setFormatError(
          `The format references the node's tag "${tag}". Please use a different format or tag.`,
        );
        setTagError(
          `The tag "${tag}" is referenced in the format. Please use a different tag or format.`,
        );
      } else {
        setTagError("");
        setFormatError("");
      }
    },
    [node.type],
  );

  useEffect(() => {
    validate({ tag: tagValue, format: formatValue });
  }, [tagValue, formatValue, validate]);

  const validateShortcut = useCallback(
    (value: string): boolean => {
      if (!value) {
        setShortcutError("");
        return true;
      }
      const normalizedValue = value.toUpperCase();
      const taken = getDiscourseNodes()
        .filter((n) => n.type !== node.type && n.shortcut)
        .map((n) => ({
          shortcut: n.shortcut.toUpperCase(),
          label: n.text,
        }));
      const matchingNodes = taken.filter((n) => n.shortcut === normalizedValue);
      if (matchingNodes.length) {
        setShortcutError(
          `Shortcut "${normalizedValue}" is already used by: ${matchingNodes
            .map((n) => `"${n.label}"`)
            .join(", ")}.`,
        );
        return false;
      }
      setShortcutError("");
      return true;
    },
    [node.type],
  );

  const handleShortcutChange = useCallback(
    (value: string) => {
      if (validateShortcut(value)) {
        setShortcutValue(value);
      }
    },
    [validateShortcut],
  );

  return (
    <div className="dg-settings-node-config flex flex-col gap-6 p-1">
      <SettingsGroup {...sectionProps(NODE_CONFIG_SECTIONS.identity)}>
        <SettingItemRow
          label="Index"
          description={`A table of all ${node.text} pages.`}
          scope="global"
          settingKeys={[DISCOURSE_NODE_KEYS.index]}
          control={
            <SettingDrillDownSummary
              summary={`See all ${node.text} nodes`}
              onClick={() => nav.push(nodeConfigSegmentIds.index)}
            />
          }
        />
        <DiscourseNodeTextPanel
          nodeType={node.type}
          title="Description"
          description={`Describing what the ${node.text} node represents in your graph.`}
          settingKeys={[DISCOURSE_NODE_KEYS.description]}
          initialValue={node.description}
          multiline
          order={1}
          parentUid={node.type}
          uid={descriptionUid}
        />
        <DiscourseNodeTextPanel
          nodeType={node.type}
          title="Tag"
          description={withDocsLink(
            `Designate a hashtag for marking potential ${node.text}.`,
            ROAM_DOCS.candidateNodeTagSetup,
          )}
          settingKeys={[DISCOURSE_NODE_KEYS.tag]}
          initialValue={node.tag}
          placeholder={generateTagPlaceholder(node)}
          error={tagError}
          onChange={setTagValue}
          order={2}
          parentUid={node.type}
          uid={tagUid}
        />
        <DiscourseNodeColorSetting
          canvasUid={canvasUid}
          nodeType={node.type}
          initialColor={node.canvasSettings?.color}
          tagValue={tagValue}
        />
        <DiscourseNodeTextPanel
          nodeType={node.type}
          title="Format"
          description={`The format ${node.text} pages should have.`}
          settingKeys={[DISCOURSE_NODE_KEYS.format]}
          initialValue={node.format}
          error={formatError}
          onChange={setFormatValue}
          order={3}
          parentUid={node.type}
          uid={formatUid}
        />
      </SettingsGroup>

      <SettingsGroup {...sectionProps(NODE_CONFIG_SECTIONS.creation)}>
        <DiscourseNodeTextPanel
          nodeType={node.type}
          title="Shortcut"
          description={withDocsLink(
            `The trigger to quickly create a ${node.text} page from the node menu.`,
            ROAM_DOCS.creatingNodes,
          )}
          settingKeys={[DISCOURSE_NODE_KEYS.shortcut]}
          initialValue={node.shortcut}
          error={shortcutError}
          onChange={handleShortcutChange}
          order={0}
          parentUid={node.type}
          uid={shortcutUid}
        />
        <SettingItemRow
          label="Template"
          description={`The template that auto fills ${node.text} page when generated.`}
          scope="global"
          settingKeys={TEMPLATE_SETTING_KEYS}
          control={
            <SettingDrillDownSummary
              summary="Edit template"
              onClick={() => nav.push(nodeConfigSegmentIds.template)}
            />
          }
        />
      </SettingsGroup>

      <SettingsGroup {...sectionProps(NODE_CONFIG_SECTIONS.canvas)}>
        <DiscourseNodeCanvasSettings nodeType={node.type} uid={canvasUid} />
        <DiscourseNodeFlagPanel
          nodeType={node.type}
          title="Graph Overview"
          description="Whether to color the node in the graph overview based on canvas color.  This is based on the node's plain title as described by a \`has title\` condition in its specification."
          settingKeys={[DISCOURSE_NODE_KEYS.graphOverview]}
          initialValue={node.graphOverview}
          order={0}
          parentUid={node.type}
          uid={graphOverviewUid}
        />
      </SettingsGroup>

      <SettingsGroup {...sectionProps(NODE_CONFIG_SECTIONS.legacy)}>
        <SettingItemRow
          label="Specification"
          description={`The conditions specified to identify a ${node.text} node.`}
          scope="global"
          settingKeys={[DISCOURSE_NODE_KEYS.specification]}
          controlPlacement="below"
          control={
            <DiscourseNodeSpecification
              node={node}
              parentUid={specificationUid}
              parentSetEnabled={(isSpecificationEnabled) => {
                validate({
                  tag: tagValue,
                  format: formatValue,
                  isSpecificationEnabled,
                });
              }}
            />
          }
        />
      </SettingsGroup>

      {isSyncEnabled() && (
        <SettingsGroup {...sectionProps(NODE_CONFIG_SECTIONS.suggestiveMode)}>
          <DiscourseNodeSuggestiveRules
            node={node}
            parentUid={suggestiveRulesUid}
          />
        </SettingsGroup>
      )}

      <SettingsGroup {...sectionProps(NODE_CONFIG_SECTIONS.attributes)}>
        <DiscourseNodeAttributes
          uid={attributeNode.uid}
          nodeType={node.type}
          defaultValue={getDiscourseNodeSetting<Record<string, string>>(
            node.type,
            [DISCOURSE_NODE_KEYS.attributes],
          )}
        />
        <DiscourseNodeSelectPanel
          nodeType={node.type}
          title="Overlay"
          description={withDocsLink(
            "Select which attribute is used for the discourse overlay",
            ROAM_DOCS.discourseScore,
          )}
          settingKeys={[DISCOURSE_NODE_KEYS.overlay]}
          options={attributeNode.children.map((c) => c.text)}
          initialValue={
            getDiscourseNodeSetting<string>(node.type, [
              DISCOURSE_NODE_KEYS.overlay,
            ]) ?? ""
          }
          order={0}
          parentUid={node.type}
          uid={overlayUid}
        />
      </SettingsGroup>
    </div>
  );
};

export default NodeConfig;

import React, { useEffect } from "react";
import { Button } from "@blueprintjs/core";
import { OnloadArgs } from "roamjs-components/types";
import getDiscourseNodes, {
  excludeDefaultNodes,
} from "~/utils/getDiscourseNodes";
import { nodeConfigSegmentIds } from "./utils/settingsNavigation";
import { useSettingsNav } from "./navigation/SettingsNavContext";
import SettingsPageHeader from "./navigation/SettingsPageHeader";
import DiscourseNodeConfigPanel from "./DiscourseNodeConfigPanel";
import NodeConfig from "./NodeConfig";
import NodeIndexPage from "./NodeIndexPage";
import NodeTemplatePage from "./NodeTemplatePage";
import { isSyncEnabled } from "./utils/accessors";
import {
  CollapsedSections,
  areAllSectionsCollapsed,
  getNodeConfigSections,
  toggleAllSections,
  toggleSection,
} from "./utils/nodeConfigSections";

const NODES_ANCESTOR_LABELS = ["Grammar"] as const;

const SUB_PAGE_LABELS: Record<string, string | undefined> = {
  [nodeConfigSegmentIds.index]: "Index",
  [nodeConfigSegmentIds.template]: "Template",
};

const GrammarNodesRoute = ({
  onloadArgs,
  collapsedSections,
  setCollapsedSections,
}: {
  onloadArgs: OnloadArgs;
  collapsedSections: CollapsedSections;
  setCollapsedSections: React.Dispatch<React.SetStateAction<CollapsedSections>>;
}): JSX.Element => {
  const { segments, goToDepth } = useSettingsNav();
  const nodes = getDiscourseNodes().filter(excludeDefaultNodes);

  const [nodeTypeUid, subPage] = segments;
  const node = nodeTypeUid
    ? nodes.find((n) => n.type === nodeTypeUid)
    : undefined;

  // A deleted node type or stale deep link resolves to nothing; return to the list.
  const isStalePath = Boolean(nodeTypeUid) && !node;
  useEffect(() => {
    if (isStalePath) goToDepth(0);
  }, [isStalePath, goToDepth]);

  const resolveLabel = (segment: string, segmentIndex: number): string =>
    segmentIndex === 0
      ? (nodes.find((n) => n.type === segment)?.text ?? segment)
      : (SUB_PAGE_LABELS[segment] ?? segment);

  const sections =
    node && !subPage
      ? getNodeConfigSections({ isSyncEnabled: isSyncEnabled() })
      : null;
  const allCollapsed =
    !!sections && areAllSectionsCollapsed(collapsedSections, sections);

  return (
    <div className="flex h-full flex-col">
      <SettingsPageHeader
        ancestorLabels={NODES_ANCESTOR_LABELS}
        rootLabel="Nodes"
        resolveLabel={resolveLabel}
        actions={
          sections && (
            <Button
              minimal
              small
              icon={allCollapsed ? "expand-all" : "collapse-all"}
              text={allCollapsed ? "Expand all" : "Collapse all"}
              onClick={() =>
                setCollapsedSections((prev) =>
                  toggleAllSections(prev, sections),
                )
              }
            />
          )
        }
      />
      {/* `-mx-1 px-1` widens the scroll box so the search flash is not clipped; content stays put. */}
      <div className="-mx-1 min-h-0 flex-auto overflow-y-auto px-1">
        {!node ? (
          <div className="p-1">
            <DiscourseNodeConfigPanel />
          </div>
        ) : /* Keyed by node: search can jump straight between node pages, and these forms seed
             their state from props once, so without a remount the previous node's values stay. */
        subPage === nodeConfigSegmentIds.index ? (
          <NodeIndexPage key={node.type} node={node} onloadArgs={onloadArgs} />
        ) : subPage === nodeConfigSegmentIds.template ? (
          <NodeTemplatePage key={node.type} node={node} />
        ) : (
          <NodeConfig
            key={node.type}
            node={node}
            collapsedSections={collapsedSections}
            onToggleSection={(section) =>
              setCollapsedSections((prev) => toggleSection(prev, section))
            }
          />
        )}
      </div>
    </div>
  );
};

export default GrammarNodesRoute;
