const DEBOUNCE_MS = 250;

const BaseTextPanel = ({
  title,
  description,
  settingKeys,
  setter,
  initialValue,
  placeholder,
  multiline,
  error,
  disabled,
  onChange,
  parentUid,
  uid,
  order,
  blockKey,
  scope,
  inline,
}: BaseTextPanelProps) => {
  const [value, setValue] = useState(() => initialValue ?? "");
  const errorRef = useRef(error);
  errorRef.current = error;
  const debounceRef = useRef(0);
  const hasBlockSync = parentUid !== undefined && order !== undefined;
  const { onChange: rawSyncToBlock } = useSingleChildValue({
    title: blockKey ?? title,
    parentUid: parentUid ?? "",
    order: order ?? 0,
    uid,
    defaultValue: initialValue ?? "",
    transform: (s: string) => s,
    toStr: (s: string) => s,
  });
  const syncToBlock = hasBlockSync ? rawSyncToBlock : undefined;

  useEffect(() => {
    return () => window.clearTimeout(debounceRef.current);
  }, []);

  const handleChange = (
    e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => {
    const newValue = e.target.value;
    setValue(newValue);
    onChange?.(newValue);

    window.clearTimeout(debounceRef.current);
    debounceRef.current = window.setTimeout(() => {
      if (errorRef.current) return;
      syncToBlock?.(newValue);
      debounceRef.current = window.setTimeout(() => {
        if (errorRef.current) return;
        refreshConfigTree();
        setter(settingKeys, newValue);
      }, 100);
    }, DEBOUNCE_MS);
  };

  return (
    <SettingItemRow
      label={title}
      description={description}
      scope={scope}
      inline={inline}
      settingKeys={settingKeys}
      error={error}
      controlPlacement={multiline ? "below" : "trailing"}
      control={(controlId) =>
        multiline ? (
          <TextArea
            id={controlId}
            value={value}
            onChange={handleChange}
            placeholder={placeholder || initialValue}
            className="w-full"
            style={{ minHeight: 80, resize: "vertical" }}
            disabled={disabled}
          />
        ) : (
          <InputGroup
            id={controlId}
            value={value}
            onChange={handleChange}
            placeholder={placeholder || initialValue}
            disabled={disabled}
            className="w-56"
          />
        )
      }
    />
  );
};

const BaseFlagPanel = ({
  title,
  description,
  settingKeys,
  setter,
  initialValue,
  value,
  disabled = false,
  onBeforeChange,
  onChange,
  parentUid,
  uid: initialBlockUid,
  order,
  blockKey,
  scope,
  inline,
}: BaseFlagPanelProps) => {
  const [internalValue, setInternalValue] = useState(
    () => initialValue ?? false,
  );
  const blockUidRef = useRef(initialBlockUid);

  const syncFlagToBlock = useCallback(
    async (checked: boolean) => {
      if (parentUid === undefined || order === undefined) return;
      if (checked) {
        if (blockUidRef.current) return;
        const newUid = window.roamAlphaAPI.util.generateUID();
        await window.roamAlphaAPI.data.block.create({
          block: { string: blockKey ?? title, uid: newUid },
          location: { order, "parent-uid": parentUid },
        });
        blockUidRef.current = newUid;
      } else if (blockUidRef.current) {
        await window.roamAlphaAPI.deleteBlock({
          block: { uid: blockUidRef.current },
        });
        blockUidRef.current = undefined;
      }
    },
    [blockKey, title, parentUid, order],
  );

  const handleChange = async (e: React.FormEvent<HTMLInputElement>) => {
    const { checked } = e.target as HTMLInputElement;

    if (onBeforeChange) {
      const shouldProceed = await onBeforeChange(checked);
      if (!shouldProceed) return;
    }

    setInternalValue(checked);
    await syncFlagToBlock(checked);
    refreshConfigTree();
    setter(settingKeys, checked);
    setTimeout(() => onChange?.(checked), 100);
  };

  if (inline) {
    return (
      <div {...settingAnchor(settingKeys)}>
        <Checkbox
          checked={value ?? internalValue}
          onChange={(e) => void handleChange(e)}
          disabled={disabled}
          labelElement={
            <>
              {title}
              <Description description={description} />
            </>
          }
        />
      </div>
    );
  }
  return (
    <SettingItemRow
      label={title}
      description={description}
      scope={scope}
      settingKeys={settingKeys}
      control={(controlId) => (
        <Switch
          id={controlId}
          checked={value ?? internalValue}
          onChange={(e) => void handleChange(e)}
          disabled={disabled}
          className="mb-0"
        />
      )}
    />
  );
};

