+import React, { useEffect, useMemo, useRef, useState } from "react";
+import {
+  Icon,
+  InputGroup,
+  Menu,
+  MenuItem,
+  Popover,
+  Position,
+} from "@blueprintjs/core";
+import {
+  buildSettingsCatalog,
+  type SearchableEntry,
+} from "~/components/settings/utils/settingsCatalog";
+import { rankSettings } from "~/components/settings/utils/settingsSearch";
+
+const SettingsSearchResult = ({
+  entry,
+  isActive,
+  onSelect,
+}: {
+  entry: SearchableEntry;
+  isActive: boolean;
+  onSelect: (entry: SearchableEntry) => void;
+}): JSX.Element => (
+  <MenuItem
+    // `data-active` is what the scroll effect looks for.
+    data-active={isActive}
+    active={isActive}
+    icon={entry.kind === "page" ? "document" : "cog"}
+    shouldDismissPopover={false}
+    text={
+      <div className="flex flex-col">
+        <span>{entry.label}</span>
+        {/* Active rows inherit the white text undimmed: any opacity fails AA on #137CBD. */}
+        <span className={`text-xs ${isActive ? "" : "text-gray-500"}`}>
+          {entry.breadcrumb}
+        </span>
+      </div>
+    }
+    // Select on mousedown, before the input's blur closes the list.
+    onMouseDown={(event: React.MouseEvent) => {
+      event.preventDefault();
+      onSelect(entry);
+    }}
+  />
+);
+
+/** Results are a portalled Popover because the tab list this field sits in is styled
+ *  `overflow-y: auto; overflow-x: hidden`, which clips an in-flow dropdown on both axes. */
+const SettingsSearchField = ({
+  onSelect,
+}: {
+  onSelect: (entry: SearchableEntry) => void;
+}): JSX.Element => {
+  const [query, setQuery] = useState("");
+  const [activeIndex, setActiveIndex] = useState(0);
+  const [isOpen, setIsOpen] = useState(false);
+  const inputRef = useRef<HTMLInputElement | null>(null);
+  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
+
+  const results = useMemo(
+    () => rankSettings({ entries: buildSettingsCatalog(), query }),
+    [query],
+  );
+  const isShowingResults = isOpen && query.trim() !== "";
+
+  // Keeps the keyboard-selected row visible.
+  useEffect(() => {
+    const container = scrollContainerRef.current;
+    if (!container) return;
+    const activeItem = container.querySelector<HTMLElement>(
+      '[data-active="true"]',
+    );
+    if (!activeItem) return;
+    const containerRect = container.getBoundingClientRect();
+    const itemRect = activeItem.getBoundingClientRect();
+    if (
+      itemRect.bottom > containerRect.bottom ||
+      itemRect.top < containerRect.top
+    ) {
+      activeItem.scrollIntoView({ block: "nearest", behavior: "auto" });
+    }
+  }, [activeIndex, results]);
+
+  const select = (entry: SearchableEntry) => {
+    onSelect(entry);
+    setQuery("");
+    setIsOpen(false);
+    inputRef.current?.blur();
+  };
+
+  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
+    if (event.key === "Escape") {
+      // Escape clears the query instead of closing the dialog.
+      if (query !== "") event.stopPropagation();
+      setQuery("");
+      setIsOpen(false);
+      return;
+    }
+    if (!isShowingResults || results.length === 0) return;
+    if (event.key === "ArrowDown") {
+      event.preventDefault();
+      setActiveIndex((index) => (index + 1) % results.length);
+    } else if (event.key === "ArrowUp") {
+      event.preventDefault();
+      setActiveIndex((index) => (index - 1 + results.length) % results.length);
+    } else if (event.key === "Enter") {
+      event.preventDefault();
+      const entry = results[activeIndex];
+      if (entry) select(entry);
+    }
+  };
+
+  return (
+    <Popover
+      isOpen={isShowingResults}
+      // `flip`/`preventOverflow` off: the rail is at the window edge, so Blueprint's
+      // overflow handling pushes the list off the dialog instead of across it.
+      position={Position.BOTTOM_LEFT}
+      modifiers={{
+        flip: { enabled: false },
+        preventOverflow: { enabled: false },
+      }}
+      minimal={true}
+      autoFocus={false}
+      enforceFocus={false}
+      fill={true}
+      content={
+        // Inside Menu either way, so the host theme paints the surface.
+        <div className="max-h-80 overflow-y-auto" ref={scrollContainerRef}>
+          <Menu className="w-96">
+            {results.length === 0 ? (
+              <li className="flex items-center gap-2 p-2 text-sm text-gray-500">
+                <Icon icon="search" iconSize={12} />
+                <span>No settings match “{query.trim()}”</span>
+              </li>
+            ) : (
+              results.map((entry, index) => (
+                <SettingsSearchResult
+                  key={entry.id}
+                  entry={entry}
+                  isActive={index === activeIndex}
+                  onSelect={select}
+                />
+              ))
+            )}
+          </Menu>
+        </div>
+      }
+    >
+      {/* Inset to the tab titles' left edge. */}
+      <div className="mx-2.5 mb-2 mt-1">
+        <InputGroup
+          inputRef={(input) => {
+            inputRef.current = input;
+          }}
+          leftIcon="search"
+          placeholder="Search settings"
+          value={query}
+          onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
+            setQuery(event.target.value);
+            setActiveIndex(0);
+            setIsOpen(true);
+          }}
+          onFocus={() => setIsOpen(true)}
+          onBlur={() => setIsOpen(false)}
+          onKeyDown={handleKeyDown}
+        />
+      </div>
+    </Popover>
+  );
+};
+
+export default SettingsSearchField;
