+    if (!scroller || !root) return;
+    scroller.scrollTop +=
+      root.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
+  }, [isOpen]);
+
+  const toggle = (): void => {
+    if (!collapsible) return;
+    const root = rootRef.current;
+    const scroller = root ? getScrollParent(root) : null;
+    const isStuck =
+      !!root &&
+      !!scroller &&
+      root.getBoundingClientRect().top < scroller.getBoundingClientRect().top;
+    scrollerToRealign.current = isOpen && isStuck ? scroller : null;
+    collapsible.onToggle();
+  };
+
+  return (
+    <div ref={rootRef} className="flex flex-col gap-1">
+      {collapsible ? (
+        <StickyHeading
+          className="flex cursor-pointer items-center gap-1"
+          role="button"
+          tabIndex={0}
+          aria-expanded={isOpen}
+          aria-controls={contentId}
+          onClick={toggle}
+          onKeyDown={(e) => {
+            if ((e.key !== "Enter" && e.key !== " ") || e.repeat) return;
+            e.preventDefault();
+            toggle();
+          }}
+        >
+          <Icon icon={isOpen ? "chevron-down" : "chevron-right"} />
+          {title}
+        </StickyHeading>
+      ) : (
+        <StickyHeading>{title}</StickyHeading>
+      )}
+      {collapsible ? (
+        // keepChildrenMounted so pending setting writes and search anchors survive a collapse.
+        <Collapse isOpen={isOpen} keepChildrenMounted>
+          <div ref={contentRef} id={contentId} className="flex flex-col gap-4">
+            {children}
+          </div>
+        </Collapse>
+      ) : (
+        <div className="flex flex-col gap-4">{children}</div>
+      )}
+    </div>
+  );
+};
